import json
from collections import Counter
from pathlib import Path

base = Path(__file__).resolve().parent
key = json.loads((base / 'blind-unmask-key.json').read_text())
hand = {'f1r': 1, 'f2r': 1, 'f5r': 1, 'f55v': 2, 'f75r': 2, 'f103v': 3}
mapping = {'N':'A','n':'B','m':'C'}
target = {'A','B'}
a, b = (json.loads((base / filename).read_text()) for filename in ('blind-rater-a.json', 'blind-rater-b.json'))


def broad_family(code):
    return 'curl' if code in 'ABC' else 'undecided' if code == 'U' else 'other'


def target_family(code):
    return 'target' if code in target else 'undecided' if code == 'U' else 'other'


def measure(rows):
    possible = [(r['reader_A'], r['reader_B']) for r in rows]
    decidable = [(x,y) for x,y in possible if 'U' not in (x,y)]
    totals = {'n':len(rows), 'paired_decidable':len(decidable),
              'broad_family_matches_among_decidable':sum(broad_family(x)==broad_family(y) for x,y in decidable),
              'target_subset_matches_among_decidable':sum(target_family(x)==target_family(y) for x,y in decidable),
              'variant_matches_among_decidable':sum(x==y for x,y in decidable),
              'variant_matches_including_matching_undecided':sum(x==y for x,y in possible)}
    for reader in ('reader_A','reader_B'):
        out = {}
        for gold in 'ABCD':
            got = Counter(r[reader] for r in rows if r['v101_shape'] == gold)
            if got:
                out[gold] = dict(got)
        totals[reader] = out
    return totals


assert set(a) == set(b) == {row['tile'] for row in key}
for row in key:
    row['hand'] = hand[row['locus'].split('.')[0]]
    row['v101_shape'] = mapping.get(row['v101'][-1], 'D')
    row['reader_A'] = a[row['tile']]
    row['reader_B'] = b[row['tile']]
results = {'all':measure(key), 'target_only':measure([r for r in key if r['v101_shape'] in target]),
           'by_hand':{str(h):measure([r for r in key if r['hand']==h]) for h in range(1,4)}}
def nearest_matches(rows):
    by_stem = {}
    for row in rows:
        if row['v101_shape'] == 'B':
            page = row['locus'].split('.')[0]
            by_stem.setdefault((page, row['v101'][:-1]), []).append(row)
    pairs = []
    for capital in rows:
        if capital['v101_shape'] != 'A':
            continue
        page, line = capital['locus'].split('.')
        n = int(line)
        possible = by_stem[page, capital['v101'][:-1]]

        def distance(lower):
            ln = int(lower['locus'].split('.')[1])
            return abs(ln-n), ln, abs(lower['word_ordinal']-capital['word_ordinal']), lower['word_ordinal']

        lower = min(possible, key=distance)
        annotations = {reader: capital[reader]+lower[reader] for reader in ('reader_A','reader_B')}
        pairs.append({'uppercase_tile':capital['tile'], 'lowercase_tile':lower['tile'], **annotations})
    return pairs


pairs = nearest_matches(key)
for reader in ('reader_A','reader_B'):
    counts = Counter()
    for pair in pairs:
        left, right = pair[reader]
        if left not in 'ABC' or right not in 'ABC':
            counts['unresolved'] += 1
        else:
            counts['shorter' if left < right else 'tied' if left == right else 'longer'] += 1
    results[reader + '_relative_strokes'] = dict(counts)
print(json.dumps({'measurements':results, 'nearest_pairs':pairs, 'trials':key},indent=2))
